const wordSetCache: Record<string, Set<string>> = {};

export function getLanguageWordSet(lang: string): Set<string> {
  const normalized = lang.toLowerCase();
  if (!wordSetCache[normalized]) {
    wordSetCache[normalized] = new Set(LANGUAGE_WORDS[normalized] || LANGUAGE_WORDS['python'] || []);
  }
  return wordSetCache[normalized];
}

export function getLanguageSeeds(lang: string): string[] {
  const normalized = lang.toLowerCase();
  return LANGUAGE_SEEDS[normalized] || LANGUAGE_SEEDS['python'] || [];
}

let supaDBLoaded = false;
let supaDBLoadingPromise: Promise<Set<string>> | null = null;

export async function loadFullEnglishDictionary(): Promise<Set<string>> {
  if (supaDBLoaded && wordSetCache['english']) {
    return wordSetCache['english'];
  }
  if (supaDBLoadingPromise) {
    return supaDBLoadingPromise;
  }
  supaDBLoadingPromise = (async () => {
    try {
      if (typeof window !== 'undefined' && typeof fetch !== 'undefined') {
        const resp = await fetch('/supadb1.txt');
        if (resp.ok) {
          const text = await resp.text();
          const lines = text.split('\n');
          const englishSet = getLanguageWordSet('english');
          for (let i = 0; i < lines.length; i++) {
            const w = lines[i].trim().toLowerCase();
            if (w.length >= 3) {
              englishSet.add(w);
            }
          }
          supaDBLoaded = true;
          console.info(`[Wordlists] Successfully loaded SupaDB1 dictionary with ${englishSet.size} English words.`);
        }
      } else {
        // Node.js test environment support
        try {
          const fs = await import('fs');
          const path = await import('path');
          const filePath = path.join(process.cwd(), 'public', 'supadb1.txt');
          if (fs.existsSync(filePath)) {
            const text = fs.readFileSync(filePath, 'utf8');
            const lines = text.split('\n');
            const englishSet = getLanguageWordSet('english');
            for (let i = 0; i < lines.length; i++) {
              const w = lines[i].trim().toLowerCase();
              if (w.length >= 3) {
                englishSet.add(w);
              }
            }
            supaDBLoaded = true;
          }
        } catch {
          // Ignore Node fallback failure
        }
      }
    } catch (err) {
      console.warn('[Wordlists] Failed to fetch /supadb1.txt, using bundled dictionary fallback', err);
    }
    return getLanguageWordSet('english');
  })();
  return supaDBLoadingPromise;
}

// Automatically initiate dictionary loading in the browser
if (typeof window !== 'undefined') {
  loadFullEnglishDictionary().catch(() => {});
}

